/* ===================== BÀI 17 · C tối thiểu cho phần cứng ===================== */
/* Bài 17 · C tối thiểu cho phần cứng (AMTS-EMB-001-M05-L01, MC51-017) — sinh bởi tools/author/mcu8051/l17.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P17=[{"label":"Ví dụ: Biến 8 bit và phép ~ ra cổng P1","code":"; Ví dụ 1: x = 0x05; P1 = ~x;\n; Mã SDCC 4.2.0 sinh cho 01.c51, viết lại theo cú pháp A51.\n; x ở ô 30H. LED ở P1 sáng khi chân = 0.\n        ORG     0000H\n        MOV     30H,#05H                ; x = 0x05;\n        MOV     A,30H                   ; P1 = ~x;  đọc x vào A\n        CPL     A                       ;           đảo 8 bit\n        MOV     P1,A                    ;           ghi ra cổng\n        SJMP    $                       ; while (1);\n        END\n","note":"Mỗi dòng C thành 1–3 lệnh. Bấm Từng bước: x vào ô 30H, A = 05H, CPL A cho FAH, P1 = FAH nên LED P1.0 và P1.2 sáng (đúng các bit 1 của x). 10 byte, 5 chu kỳ máy tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Biến int 16 bit cần hai lần cộng","code":"; Ví dụ 2: s = s + x với s kiểu unsigned int (16 bit)\n; Mã SDCC 4.2.0 sinh cho 03.c51. SDCC xếp byte thấp\n; của s ở 32H, byte cao ở 33H.\n        ORG     0000H\n        MOV     30H,#0C5H               ; x = 0xC5;\n        MOV     32H,#0F0H               ; s = 0x01F0;  byte thấp\n        MOV     33H,#01H                ;              byte cao\n        MOV     R6,30H                  ; s = s + x;  R7:R6 = x (16 bit)\n        MOV     R7,#00H\n        MOV     A,R6\n        ADD     A,32H                   ;   cộng byte thấp\n        MOV     32H,A\n        MOV     A,R7\n        ADDC    A,33H                   ;   cộng byte cao + cờ nhớ\n        MOV     33H,A\n        SJMP    $                       ; while (1);\n        END\n","note":"Theo dõi ô 32H, 33H trong Bộ nhớ: F0H + C5H = 1B5H nên byte thấp = B5H và CY = 1; byte cao 01H + 00H + CY = 02H. Phép cộng 16 bit tốn 8 lệnh (R7:R6 giữ x đã mở rộng), so với 3 lệnh nếu s là unsigned char.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Mảng, chỉ số và con trỏ 1 byte","code":"; Ví dụ 3: mảng a[4] ở 34H, n ở 38H, i ở 39H\n; Mã SDCC 4.2.0 sinh cho 04.c51; con trỏ p nằm ở R1.\n        ORG     0000H\n        MOV     39H,#00H                ; for (i = 0; i < 4; i++)\nVONG1:  MOV     A,#0FCH                 ;   i < 4 ? (FCH + i có nhớ\n        ADD     A,39H                   ;    khi i >= 4)\n        JC      HET1\n        MOV     A,39H                   ;   a[i] = i + 1;\n        ADD     A,#34H                  ;   R1 = địa chỉ a[i]\n        MOV     R1,A\n        MOV     A,39H\n        MOV     R7,A\n        INC     A\n        MOV     @R1,A\n        MOV     A,39H                   ;   i++\n        INC     A\n        MOV     39H,A\n        SJMP    VONG1\nHET1:   MOV     38H,#00H                ; n = 0;\n        MOV     R1,#34H                 ; p = a;\nVONG2:  CJNE    R1,#38H,THAN2           ; p != a + 4 ?\n        SJMP    XONG\nTHAN2:  MOV     07H,@R1                 ; n += *p;  (R7 = *p)\n        INC     R1                      ; p++\n        MOV     A,R7\n        ADD     A,38H\n        MOV     38H,A\n        SJMP    VONG2\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Vòng 1 dùng chỉ số i (16 chu kỳ mỗi phần tử), vòng 2 dùng con trỏ p trong R1 (10 chu kỳ mỗi phần tử). Đoán trước: khi R1 = 38H, CJNE có nhảy không? (Không: p == a + 4, vòng dừng.) Cuối cùng n = 1 + 2 + 3 + 4 = 0AH.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Gọi hàm, tham số và giá trị trả về","code":"; Ví dụ 4: y = add3(x); hàm add3 trả về v + 3\n; Mã SDCC 4.2.0 sinh cho 05.c51. Quy ước SDCC: tham số\n; 1 byte đầu tiên và giá trị trả về đi qua DPL.\n        ORG     0000H\n        MOV     30H,#0C5H               ; x = 0xC5;\n        MOV     DPL,30H                 ; y = add3(x);  tham số vào DPL\n        LCALL   ADD3                    ;   gọi hàm: cất PC vào ngăn xếp\n        MOV     31H,DPL                 ;   kết quả ở DPL\n        SJMP    $                       ; while (1);\nADD3:   MOV     R7,DPL                  ; v = tham số\n        MOV     A,#03H                  ; return v + 3;\n        ADD     A,R7\n        MOV     DPL,A\n        RET                             ; lấy PC từ ngăn xếp\n        END\n","note":"Xem phần Ngăn xếp khi LCALL: hai ô 08H, 09H nhận địa chỉ trở về 0009H. Tham số và kết quả đi qua DPL (quy ước của SDCC). y = C5H + 3 = C8H; cả lời gọi 13 chu kỳ.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: ~x bị nâng lên int 16 bit","code":"; Ví dụ 5 (bẫy): if (~x == 0x3A) ... với x = 0xC5\n; Mã SDCC 4.2.0 sinh cho 06.c51: ~x tính trên 16 bit.\n        ORG     0000H\n        MOV     30H,#0C5H               ; x = 0xC5;\n        MOV     R6,30H                  ; R7:R6 = (int)x = 00C5H\n        MOV     R7,#00H\n        MOV     A,R6                    ; ~x: đảo byte thấp\n        CPL     A\n        MOV     R6,A\n        MOV     A,R7                    ;     đảo cả byte cao\n        CPL     A\n        MOV     R7,A                    ; ~x = FF3AH\n        CJNE    R6,#3AH,KHAC            ; so byte thấp: bằng\n        CJNE    R7,#00H,KHAC            ; so byte cao: FFH khác 00H\n        MOV     P1,#00H                 ; (không chạy tới)\n        SJMP    XONG\nKHAC:   MOV     P1,#7FH                 ; else P1 = 0x7F;\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: ~x tính trên 16 bit nên R7:R6 = FF3AH. CJNE thứ nhất (3AH = 3AH) không nhảy, CJNE thứ hai (FFH ≠ 00H) nhảy sang nhánh else: chỉ LED P1.7 sáng thay vì cả 8 LED. Sửa: (unsigned char)~x.","dev":{"led":true},"fosc":12000000}];
const sim17=makeSim51(document.getElementById("m51-l17"),{id:"s17",presets:P17,ram:256});
makeEx51(document.getElementById("ex-l17"),"l17",[{"t":"Ghép hai nửa byte","d":"<p>Viết đoạn hợp ngữ làm đúng việc của câu lệnh C51 sau (biến <code>unsigned char<\/code>: <code>a<\/code> ở <code>30H<\/code>, <code>b<\/code> ở <code>31H<\/code>, <code>y<\/code> ở <code>32H<\/code>):<\/p><pre class=\"mc-asm\">y = (a &amp; 0x0F) | (b &lt;&lt; 4);<\/pre><p>Ô <code>30H<\/code>, <code>31H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>a = 05H<\/code>, <code>b = 03H<\/code> → <code>y = 35H<\/code>.<\/p>","start":"; Bài tập 1: y = (a & 0x0F) | (b << 4);\n; a ở 30H, b ở 31H, y ở 32H (unsigned char).\n        ORG     0000H\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":5,"0x31":3,"0x32":238}},"expect":{"iram":{"0x30":5,"0x31":3,"0x32":53}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255}}},{"setup":{"iram":{"0x30":167,"0x31":92,"0x32":238}},"expect":{"iram":{"0x30":167,"0x31":92,"0x32":199}}},{"setup":{"iram":{"0x30":15,"0x31":240,"0x32":238}},"expect":{"iram":{"0x30":15,"0x31":240,"0x32":15}}},{"setup":{"iram":{"0x30":240,"0x31":15,"0x32":238}},"expect":{"iram":{"0x30":240,"0x31":15,"0x32":240}}}]},"hints":["Tính hai nửa riêng: nửa thấp lấy từ a (che bằng ANL), nửa cao lấy từ 4 bit thấp của b.","b &lt;&lt; 4 cho kết quả 16 bit, nhưng y chỉ giữ 8 bit thấp: 4 bit cao của b bị mất. SWAP A rồi ANL A,#0F0H làm đúng việc đó trong 2 lệnh.","Hai nửa tính riêng; cần một chỗ giữ một nửa trong lúc tính nửa kia, rồi ghép bằng phép OR."],"why":"Phép &lt;&lt; trên unsigned char được nâng lên int, nhưng khi gán vào y (8 bit) chỉ còn 8 bit thấp, nên b &lt;&lt; 4 tương đương SWAP A + ANL A,#0F0H. Bộ thử 4 bắt lỗi quên che nửa cao của a, bộ thử 5 bắt lỗi giữ nửa cao của b."},{"t":"Tổng mảng 16 bit","d":"<p>Viết đoạn hợp ngữ làm đúng việc của đoạn C51 sau. Mảng <code>unsigned char a[5]<\/code> ở <code>30H<\/code>–<code>34H<\/code>; <code>unsigned int s<\/code> xếp như SDCC: byte thấp ở <code>38H<\/code>, byte cao ở <code>39H<\/code>.<\/p><pre class=\"mc-asm\">s = 0;\nfor (i = 0; i &lt; 5; i++) s += a[i];<\/pre><p>Mảng giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>a = 01H 02H 03H 04H 05H<\/code> → <code>38H = 0FH<\/code>, <code>39H = 00H<\/code>.<\/p>","start":"; Bài tập 2: s = tổng 5 phần tử a[0..4] (unsigned int)\n; a ở 30H..34H; s: byte thấp ở 38H, byte cao ở 39H.\n        ORG     0000H\n; Viết code ở đây\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":1,"0x31":2,"0x32":3,"0x33":4,"0x34":5,"0x38":15,"0x39":0}}},{"setup":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":0,"0x33":0,"0x34":0,"0x38":0,"0x39":0}}},{"setup":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":255,"0x31":255,"0x32":255,"0x33":255,"0x34":255,"0x38":251,"0x39":4}}},{"setup":{"iram":{"0x30":128,"0x31":128,"0x32":0,"0x33":0,"0x34":0,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":128,"0x31":128,"0x32":0,"0x33":0,"0x34":0,"0x38":0,"0x39":1}}},{"setup":{"iram":{"0x30":255,"0x31":1,"0x32":0,"0x33":0,"0x34":0,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":255,"0x31":1,"0x32":0,"0x33":0,"0x34":0,"0x38":0,"0x39":1}}},{"setup":{"iram":{"0x30":200,"0x31":100,"0x32":50,"0x33":25,"0x34":10,"0x38":238,"0x39":238}},"expect":{"iram":{"0x30":200,"0x31":100,"0x32":50,"0x33":25,"0x34":10,"0x38":129,"0x39":1}}}]},"hints":["Tổng lớn nhất là 5 × 255 = 1 275, cần 2 byte. Giữ byte thấp trong A, byte cao trong một thanh ghi khác.","Duyệt mảng bằng con trỏ R0 (MOV R0,#30H rồi ADD A,@R0 và INC R0), đếm 5 lần bằng DJNZ.","Byte cao chỉ tăng khi phép cộng byte thấp có nhớ: rẽ nhánh theo CY ngay sau mỗi ADD."],"why":"s là int nên mỗi phép cộng phải mang cờ nhớ sang byte cao. Cộng 8 bit (bỏ CY) sai ở bộ thử 3, 4, 5, 6. Keil C51 xếp int theo thứ tự ngược (byte cao ở địa chỉ thấp), nên bài ghi rõ cách xếp của SDCC."},{"t":"Đếm bit 1 nhanh hơn trình biên dịch","d":"<p>Đoạn C51 dưới đây đếm số bit 1 của <code>x<\/code> (ô <code>30H<\/code>) và ghi vào <code>n<\/code> (ô <code>31H<\/code>):<\/p><pre class=\"mc-asm\">v = x;  n = 0;\nfor (i = 0; i &lt; 8; i++) {\n    if (v &amp; 1) n++;\n    v &gt;&gt;= 1;\n}<\/pre><p>Code mẫu là mã SDCC 4.2.0 sinh cho đoạn này: đúng, 28 byte, nhưng tới 127 chu kỳ máy khi <code>x = FFH<\/code>. Hãy viết lại để với mọi <code>x<\/code>: (1) <code>31H<\/code> đúng số bit 1; (2) <code>30H<\/code> giữ nguyên; (3) chạy không quá <b>60 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>); (4) mã không quá <b>18 byte<\/b>.<\/p>","start":"; Bài tập 3: đếm số bit 1 của x (30H), ghi vào n (31H).\n; Đây là mã SDCC 4.2.0 sinh cho đề: đúng nhưng tới 127 chu kỳ.\n; Sửa để chạy <= 60 chu kỳ máy và <= 18 byte.\n        ORG     0000H\n        MOV     R7,30H                  ; v = x;\n        MOV     31H,#00H                ; n = 0;\n        MOV     R6,#00H                 ; i = 0\nVONG:   MOV     A,R7                    ; if (v & 1) n++;\n        JNB     ACC.0,BOQUA\n        MOV     A,31H\n        INC     A\n        MOV     31H,A\nBOQUA:  MOV     A,R7                    ; v >>= 1;\n        CLR     C\n        RRC     A\n        MOV     R7,A\n        INC     R6                      ; i++; i < 8 ?\n        CJNE    R6,#08H,SOSANH\nSOSANH: JC      VONG\n        SJMP    $                       ; while (1);\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":165,"0x31":238}},"expect":{"iram":{"0x30":165,"0x31":4}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":0}}},{"setup":{"iram":{"0x30":255,"0x31":238}},"expect":{"iram":{"0x30":255,"0x31":8}}},{"setup":{"iram":{"0x30":1,"0x31":238}},"expect":{"iram":{"0x30":1,"0x31":1}}},{"setup":{"iram":{"0x30":128,"0x31":238}},"expect":{"iram":{"0x30":128,"0x31":1}}},{"setup":{"iram":{"0x30":126,"0x31":238}},"expect":{"iram":{"0x30":126,"0x31":6}}}],"maxCyc":60,"maxBytes":18},"hints":["Chạy code mẫu với x = FFH và đếm: mỗi vòng tốn 12 chu kỳ, cộng 3 chu kỳ khi bit bằng 1. Phần đắt là sao chép qua lại giữa A và R7 và lệnh so sánh CJNE + JC.","RRC A đưa bit thấp nhất vào cờ CY trong 1 chu kỳ; JNC nhảy qua lệnh đếm khi bit bằng 0. Giữ x trong A suốt vòng lặp, không chép lại vào R7.","Phần đếm vòng đắt nhất: một lệnh vừa giảm vừa nhảy thay được cặp tăng–so sánh–nhảy; bộ đếm kết quả tăng thẳng được trong ô nhớ."],"why":"SDCC giữ v trong R7 nên mỗi vòng phải MOV A,R7 hai lần và so i bằng CJNE + JC. Giữ v trong A, dùng RRC + JNC và DJNZ, mỗi vòng còn 5–6 chu kỳ: tối đa 4 + 8 × 6 + 2 = 54 chu kỳ, 16 byte."}]);

makeQuiz("quiz17","score17",[{"q": "Với unsigned char x = 0x05, sau P1 = ~x; những LED nào ở P1 sáng (LED sáng khi chân = 0)?", "o": ["Mọi LED trừ P1.0 và P1.2", "P1.0 và P1.2", "Không LED nào, vì ~x là số âm", "P1.0 và P1.2 nhưng chỉ khi P1 khai báo là int"], "a": 1, "e": "~05H = FAH = 1111 1010B: chân P1.0 và P1.2 bằng 0 nên hai LED đó sáng. Gán vào P1 (8 bit) chỉ giữ 8 bit thấp của kết quả int, nên không có chuyện “số âm” ở cổng."}, {"q": "SDCC dịch dòng P1 &= ~0x80; thành lệnh nào?", "o": ["ANL P1,#80H", "CPL P1.7", "MOV A,P1 · CPL A · ANL A,#80H · MOV P1,A", "ANL P1,#7FH"], "a": 3, "e": "Trình biên dịch tính sẵn ~0x80 = 7FH rồi dùng lệnh đọc–sửa–ghi ANL trực tiếp trên P1 (3 byte, 2 chu kỳ). ANL P1,#80H là nhầm mặt nạ: xóa 7 bit thấp thay vì xóa bit 7."}, {"q": "unsigned char x = 0xC5; Biểu thức (~x == 0x3A) có giá trị gì theo chuẩn C?", "o": ["1 (đúng), vì ~0xC5 = 0x3A", "Tùy cổng P1 đang ở mức nào", "0 (sai), vì ~x là int bằng 0xFF3A", "Trình biên dịch báo lỗi kiểu"], "a": 2, "e": "x được nâng lên int (0x00C5) trước khi đảo bit, nên ~x = 0xFF3A ≠ 0x003A. Muốn so 8 bit phải ép kiểu: (unsigned char)~x == 0x3A."}, {"q": "Mảng unsigned char a[4] ở 34H–37H, biến n ở 38H. Vòng for (i = 0; i <= 4; i++) a[i] = 0; làm gì với n?", "o": ["Không đổi n, vì C dừng ở a[3]", "Trình biên dịch báo lỗi vượt biên", "Ghi n = 0, vì a[4] chính là ô 38H", "Chương trình dừng với lỗi khi chạy"], "a": 2, "e": "C không kiểm tra biên mảng: a[4] là địa chỉ 34H + 4 = 38H. Trình biên dịch sinh MOV @R0,#00H với R0 = 38H mà không cảnh báo."}, {"q": "Theo quy ước gọi hàm của SDCC cho 8051, hàm unsigned char add3(unsigned char v) nhận v và trả kết quả ở đâu?", "o": ["Cả hai ở DPL", "v ở A, kết quả ở A", "v ở R7, kết quả ở R7", "Cả hai trên ngăn xếp"], "a": 0, "e": "SDCC truyền tham số 1 byte đầu tiên và trả giá trị 1 byte qua DPL (ví dụ 4). R7 là quy ước của Keil C51; trộn hai quy ước khi ghép hàm hợp ngữ với C là lỗi thường gặp."}]);

